# =====================================================================
# THE CELLS OF THE BLESSING, I — F1 the man of God and the theophany (33:1-2), F2 the prologue — the law and the king (33:3-5), F3 Reuben and Judah (33:6-7), F4 Levi (33:8-11) — each ask a case; the verdicts DATA rows or PARAMETERS, never the ink's
# =====================================================================
D1 = "Moses' last day (40, 12, 7) — 19b's marker at 31:1, no marker here"
def SV(x, n=60):
    """a callee's value as a short string — a tuple's verdict, a q-cell's v, a DATA row's value (the print decides the literal)"""
    y = x[0] if isinstance(x, tuple) else (x.get('v') if isinstance(x, dict) and 'v' in x else (x.get('value') if isinstance(x, dict) and 'value' in x else x))
    return str(y)[:n]
def the_man_of_god_and_the_theophany(case, data):
    """F1 — Deut 33:1-2 — ONE LINE moses_blessed_israel_before_his_death (ACT — the frame) writing blessing_given_before_moses_death, the_lord_came_from_sinai_seir_paran_declared and fiery_law_from_his_right_hand_declared (STATUSES on Israel); 4:44's frame by CALL (obey_horeb), the death 34:5 AHEAD (song_charge_nebo by CALL), Isaac's and Jacob's 'before his death' (family by CALL); Sinai's descent a RUN CITATION (exodus_story by CALL), the Torah offered and refused (pre_sinai by CALL — Tosefta Avodah Zarah 9:4 the case), Ebal's seventy tongues (firstfruits_ebal_curses by CALL — Sotah 7:5 the case), Berakhot 4:3 the case; the ketiv and the qere of the fiery law"""
    del P_[:]
    ask = case['ask']
    if ask == 'and_this_is_the_blessing_which_moses_the_man_of_god_blessed_the_children_of_israel_before_his_death':
        ink('33:1', "'AND THIS IS THE BLESSING WHICH MOSES THE MAN OF GOD BLESSED THE CHILDREN OF ISRAEL BEFORE HIS DEATH' — 4:44's frame five in order (the kin computed %s; the twin diffed %d), 'the man of God' once in the Torah (Joshua 14:6's twin %d — the Prophets' seat cited never read; Onkelos THE PROPHET OF THE LORD), 'before his death' Isaac's and Jacob's (Genesis 27:10 %d shared; 50:16)" % (KINC[(33, 1)][0], TWIN['33:1 vs 4:44'], TWIN['33:1 vs Josh 14:6'], TWIN['33:1 vs Gen 27:10']))
        move("cold_run_obey_horeb (CALL) — OH.DATA the_second_frame = %s (4:44's 'and this is the law' — the frame the blessing's); cold_run_song_charge_nebo (CALL) — SC.DATA moses_death_ahead = %s (the death 34:5 AHEAD — the three gifts' daemon owed there); cold_run_family (CALL) — FA.testament(firstborn_my_strength) = %s (the testament's frame — Jacob's blessing before his death, the sons' ledgers written on)" % (SV(OH_FRAME, 60), SV(SC_DEATH, 60), SV(FA_FIRSTBORN, 40)), "342:1 THE HARD WORDS FIRST (32:24-25's hunger and sword), 342:2-7 the blessing after the rebuke: THE DATA ROW the_three_parts_of_the_blessing; THE WRITE blessing_given_before_moses_death — a STATUS on israel_people (DO2), the frame's ACT at Moses' last day, NO MARKER")
        dat("THE LINE moses_blessed_israel_before_his_death (an ACT) at %s; THE WRITE blessing_given_before_moses_death, a STATUS on israel_people; the readback row 33:1 SUPPLIED with its writes; MISHNAH BERAKHOT 4:3 THE CASE at 343:3 — THE PARAMETER the_eighteen_blessings a DATA note" % D1)
        return out("and this is the blessing which Moses the man of God blessed the children of Israel before his death (33:1) — the frame's ACT at Moses' last day (the death 34:5 AHEAD: %s): THE WRITE blessing_given_before_moses_death, a STATUS on Israel; the hard words first, the blessing after (342:1)" % (SV(SC_DEATH, 40),), ['blessing_given_before_moses_death'])
    if ask == 'the_lord_came_from_sinai_and_rose_from_seir_unto_them_he_shone_from_mount_paran':
        ink('33:2', "'and he said: THE LORD CAME FROM SINAI, AND ROSE FROM SEIR UNTO THEM; HE SHONE FROM MOUNT PARAN' — the frame's first 'and he said' with the Name its object (Moses speaking); Sinai's descent the tape's own line (lord_descended at Exodus 19:18 — a RUN CITATION); Habakkuk 3:3's twin diffed %d (the Prophets' seat cited never read); Paran 1:1's and 33:2's (%s)" % (TWIN['33:2 vs Hab 3:3'], KINC[(33, 2)][0]))
        move("cold_run_exodus_story (CALL) — ES.sinai(new_moon) = %s (the descent's day); cold_run_pre_sinai (CALL) — PS.noahide(seven_list) = %s — THE TORAH OFFERED TO THE NATIONS AND REFUSED (343:6-7: Esau's sons for 'you shall not murder', Ammon and Moab for 'you shall not commit adultery', Ishmael's for 'you shall not steal'; TOSEFTA AVODAH ZARAH 9:4 THE CASE — the seven commandments); cold_run_firstfruits_ebal_curses (CALL) — FE.DATA the_things_without_measure = %s (27's stones: MISHNAH SOTAH 7:5 THE CASE at 343:5 — the Torah written on Ebal's stones in seventy tongues); cold_run_opening_speech (CALL) — OS.the_bypass(the_route) = %s (Seir's stations by reference)" % (SV(ES_SINAI, 30), SV(PS_LIST, 60), SV(FE_MEASURE, 40), SV(OS_ROUTE, 40)), "343:1-7 THE THREE PARTS OF A PRAYER — praise (33:2-4), plea (33:5 on), praise again (33:26); THE WRITE the_lord_came_from_sinai_seir_paran_declared — a STATUS on israel_people; THE PARAMETERS the_seven_commandments_of_the_nations (the nations could not keep them), the_seventy_tongues_on_ebal (a DATA note)")
        dat("THE WRITE the_lord_came_from_sinai_seir_paran_declared, a STATUS on israel_people at %s; the readback row 33:2 REFERENCE (Sinai's line by kind); THE PARAMETERS the_seven_commandments_of_the_nations, the_seventy_tongues_on_ebal — Tosefta Avodah Zarah 9:4 and Mishnah Sotah 7:5 THE CASES" % D1)
        return out("the LORD came from Sinai, rose from Seir, shone from mount Paran (33:2) — Sinai's descent a RUN CITATION of the tape's own line; the Torah offered to the nations and refused, the seven commandments the case (by CALL to pre_sinai: %s): THE WRITE the_lord_came_from_sinai_seir_paran_declared, a STATUS on Israel; the parameters the answer sheet's" % (SV(PS_LIST, 40),), ['the_lord_came_from_sinai_seir_paran_declared'])
