    """RB — THE READBACK TABLE (THE LOOP's step 6 — the forms on file, no new form): twenty-nine rows one per verse, graded against the kin's cells by CALL and the tape's lines by kind; the eleven rows SUPPLIED with their writes; no receipt; THE TWO POINTER ROWS 33:5 and 33:28 (20b's owed pointers PAID); 33:21 and 33:29 FORWARD; the blessing's pasts reference rows, its futures statuses; NO state, open or stretch row; NO marker"""
    del P_[:]
    ask = case['ask']
    R = data['the_readback']['value']
    if ask == 'the_table':
        ink('33:1-29', 'twenty-nine verses, %d rows; the grades %s' % (len(R), dict(collections.Counter(r['grade'] for r in R))))
        dat('the table a DATA row (the_readback); every row has kin — by CALL %d, on the tape %d' % (sum(1 for r in R if r['cell']), sum(1 for r in R if r['tape_kind'])))
