    if ask == 'the_state_and_the_pointers':
        ink('33:5, 33:28', 'state rows %s, pointer rows %s, open rows %s, stretch rows %s' % ([r['verses'] for r in R if r['state']], [r['verses'] for r in R if r['pointer']], [r['verses'] for r in R if r['open']], [r['verses'] for r in R if r['stretch']]))
        dat("NO STATE ROW — no two-armed condition in a blessing (33:29's enemies a declared future inside a blessing); THE TWO POINTER ROWS 33:5 (346:2 — the Shekhinah among ten) and 33:28 (356:5 and 356:8 — the three alones and the dew), grade R — 20b's owed rows paid in their own piskaot; no open row (the sanctuary's tribe an OPEN PARAMETER inside F5), no stretch")
        return out("the pointer rows at 33:5 and 33:28 (20b's owed rows paid — grade R); no state row (no two-armed condition in a blessing); no open, no stretch row — the forms on file, no new form", ['accepted'])
